stars.script:
function setMyUsername() {
            const user = tg?.initDataUnsafe?.user;
            const input = document.getElementById('username');
            if (input) {
                if (user && user.username) input.value = '@' + user.username;
                else if (user && user.id) input.value = user.id;
                else input.value = '@men';
            }
        }

        async function buyStarTier(qty, price, btn) {
            let uVal = (document.getElementById('username')?.value || '').trim().replace(/^@/, '');
            if (!uVal) {
                const tgUser = tg?.initDataUnsafe?.user;
                if (tgUser?.username) uVal = tgUser.username;
                else if (tgUser?.id) uVal = String(tgUser.id);
            }

            if (!uVal) {
                if (tg?.showAlert) tg.showAlert('Iltimos, Telegram foydalanuvchi nomini kiriting!');
                else alert('Iltimos, Telegram foydalanuvchi nomini kiriting!');
                return;
            }

            const oldText = btn.textContent;
            btn.disabled = true;
            btn.textContent = '⏳ ...';

            const userId = getUserId();
            const apiBase = (typeof getApiBase === 'function' ? getApiBase() : (window.API_BASE || 'https://web-production-4014a4.up.railway.app')) || 'https://web-production-4014a4.up.railway.app';
            const endpoint = apiBase.replace(/\/$/, '') + '/api/order/stars';

            try {
                const res = await fetch(endpoint, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg?.initData || '' },
                    body: JSON.stringify({
                        telegram_id: userId,
                        username: uVal,
                        quantity: qty,
                        amount: price,
                        product_type: 'stars',
                        initData: tg?.initData || ''
                    })
                });

                let data = null;
                try {
                    data = await res.json();
                } catch(e) {}

                if (data && data.ok) {
                    if (tg?.showAlert) tg.showAlert(`✅ ${qty} Stars muvaffaqiyatli xarid qilindi!`);
                    else alert(`✅ ${qty} Stars muvaffaqiyatli xarid qilindi!`);
                    setTimeout(() => window.location.href = 'orders.html', 1000);
                } else {
                    const err = data?.error || (res.status !== 200 ? `Server xatosi (${res.status})` : 'Xaridda xatolik yuz berdi.');
                    if (tg?.showAlert) tg.showAlert(err);
                    else alert(err);
                }
            } catch (err) {
                console.error("Order stars error:", err);
                const msg = err?.message || String(err);
                if (tg?.showAlert) tg.showAlert("Aloqa xatosi: " + msg);
                else alert("Aloqa xatosi: " + msg);
            } finally {
                btn.disabled = false;
                btn.textContent = oldText;
            }
        }

        function calcCustomStarPrice() {
            const input = document.getElementById('customStarInput');
            const preview = document.getElementById('customPricePreview');
            let qty = parseInt(input?.value || '0', 10);
            if (isNaN(qty) || qty < 1) qty = 0;
            const price = qty * 198;
            if (preview) preview.textContent = price.toLocaleString('uz-UZ');
            return { qty, price };
        }

        function setQuickStars(qty) {
            const input = document.getElementById('customStarInput');
            if (input) {
                input.value = qty;
                calcCustomStarPrice();
            }
            document.querySelectorAll('.quick-chip-btn').forEach(btn => {
                btn.classList.toggle('active', parseInt(btn.textContent.replace(/\s/g, ''), 10) === qty);
            });
        }

        async function buyCustomStars(btn) {
            const { qty, price } = calcCustomStarPrice();
            if (qty < 50) {
                if (tg?.showAlert) tg.showAlert('Minimal Telegram Stars miqdori: 50 Stars');
                else alert('Minimal Telegram Stars miqdori: 50 Stars');
                return;
            }
            await buyStarTier(qty, price, btn);
        }

        document.addEventListener('DOMContentLoaded', () => {
            setMyUsername();
            loadUserBalance();
            calcCustomStarPrice();
        });

