            { id: 'cake', name_uz: 'Bayram Torti', name_ru: 'Праздничный Торт', name_en: 'Birthday Cake', category: '50', stars: 50, price: 10000, img: 'images/cake.webp?v=3', badge: '50⭐' },
            { id: 'rocket', name_uz: 'Kosmik Raketa', name_ru: 'Космическая Ракета', name_en: 'Space Rocket', category: '50', stars: 50, price: 10000, img: 'images/rocket.webp?v=3', badge: '50⭐' },
            { id: 'heart', name_uz: 'Oltin Yurak', name_ru: 'Золотое Сердце', name_en: 'Golden Heart', category: '50', stars: 50, price: 10000, img: 'images/heart.webp?v=3', badge: '50⭐' },
            { id: 'aprel_bear', name_uz: 'Aprel Ayiqchasi', name_ru: 'Апрельский Мишка', name_en: 'April Bear', category: '50', stars: 50, price: 10000, img: 'images/aprel_bear.webp?v=3', badge: '50⭐' },
            { id: 'easter_bear', name_uz: 'Pasxa Ayiqchasi', name_ru: 'Пасхальный Мишка', name_en: 'Easter Bear', category: '50', stars: 50, price: 10000, img: 'images/easter_bear.webp?v=3', badge: '50⭐' },
            { id: 'newyear_bear', name_uz: 'Qorbobo Ayiqchasi', name_ru: 'Новогодний Мишка', name_en: 'Santa Bear', category: '50', stars: 50, price: 10000, img: 'images/newyear_bear.webp?v=3', badge: '50⭐' },
            { id: 'builder_bear', name_uz: 'Usta Ayiqchasi', name_ru: 'Мишка Строитель', name_en: 'Builder Bear', category: '50', stars: 50, price: 10000, img: 'images/builder_bear.webp?v=3', badge: '50⭐' },
            { id: 'football_bear', name_uz: 'Futbolchi Ayiqcha', name_ru: 'Мишка Футболист', name_en: 'Football Bear', category: '50', stars: 50, price: 10000, img: 'images/football_bear.webp?v=3', badge: '50⭐' },
            { id: 'soldier_bear', name_uz: 'Jangchi Ayiqchasi', name_ru: 'Мишка Солдат', name_en: 'Soldier Bear', category: '50', stars: 50, price: 10000, img: 'images/soldier_bear.webp?v=3', badge: '50⭐' },
            { id: 'newyear_tree', name_uz: 'Yangi Yil Archasi', name_ru: 'Новогодняя Ёлка', name_en: 'Christmas Tree', category: '50', stars: 50, price: 10000, img: 'images/newyear_tree.webp?v=3', badge: '50⭐' },
            { id: 'patrick_bear', name_uz: 'Patrik Ayiqchasi', name_ru: 'Мишка Патрик', name_en: 'Patrick Bear', category: '50', stars: 50, price: 10000, img: 'images/patrick_bear.webp?v=3', badge: '50⭐' },
            { id: 'valentine_bear', name_uz: 'Valentin Ayiqchasi', name_ru: 'Мишка Валентин', name_en: 'Valentine Bear', category: '50', stars: 50, price: 10000, img: 'images/valentine_bear.webp?v=3', badge: '50⭐' },

            // 100 Stars
            { id: 'diamond', name_uz: 'Brilliant', name_ru: 'Бриллиант', name_en: 'Diamond', category: '100', stars: 100, price: 20000, img: 'images/diamond.webp?v=3', badge: '100⭐' },
            { id: 'ring', name_uz: 'Olmos Uzuk', name_ru: 'Кольцо с Бриллиантом', name_en: 'Diamond Ring', category: '100', stars: 100, price: 20000, img: 'images/ring.webp?v=3', badge: '100⭐' },
            { id: 'trophy', name_uz: 'Oltin Kubok', name_ru: 'Золотой Кубок', name_en: 'Golden Trophy', category: '100', stars: 100, price: 20000, img: 'images/trophy.webp?v=3', badge: '100⭐' }
        ];

        let currentCategory = 'all';
        let searchQuery = '';
        let selectedGift = null;
        let lastPurchasedGift = null;
        let lastPurchasedUsername = '';

        function getGiftName(g) {
            if (!g) return '';
            const lang = (typeof currentLang !== 'undefined' ? currentLang : (localStorage.getItem('starpay_lang') || 'uz'));
            return g['name_' + lang] || g.name_uz || g.name || '';
        }

        function renderGifts() {
            const grid = document.getElementById('giftsGrid');
            if (!grid) return;
            
            let filtered = currentCategory === 'all' ? ALL_GIFTS : ALL_GIFTS.filter(g => g.category === currentCategory);
            
            if (searchQuery) {
                const q = searchQuery.toLowerCase().trim();
                filtered = filtered.filter(g => {
                    const uz = (g.name_uz || '').toLowerCase();
                    const ru = (g.name_ru || '').toLowerCase();
                    const en = (g.name_en || '').toLowerCase();
                    return uz.includes(q) || ru.includes(q) || en.includes(q) || String(g.stars).includes(q);
                });
            }

            if (!filtered.length) {
                grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 40px 10px; color: #64748b; font-weight: 700; font-size: 13px;">Sovg\'a topilmadi</div>';
                return;
            }

            grid.innerHTML = filtered.map(g => {
                const gName = getGiftName(g);
                return `
                <div class="gift-card" onclick="openOrderModal('${g.id}')">
                    <span class="gift-card-badge">${g.badge}</span>
                    <div class="gift-card-icon-wrap"><img src="${g.img}" alt="${gName}" loading="lazy" decoding="async" width="52" height="52"></div>
                    <div class="gift-card-name">${gName}</div>
                    <div class="gift-card-stars">⭐ ${g.stars} Stars</div>
                    <button type="button" class="gift-card-buy-btn">${g.price.toLocaleString('uz-UZ')} UZS</button>
                </div>
            `}).join('');
        }

        function filterGifts(category, btn) {
            currentCategory = category;
            document.querySelectorAll('.category-chip').forEach(c => c.classList.remove('active'));
            if (btn) btn.classList.add('active');
            renderGifts();
            if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.selectionChanged();
        }

        function onSearchGifts(val) {
            searchQuery = val || '';
            renderGifts();
        }

        function setRecipientMode(mode) {
            const tabSelf = document.getElementById('tabSelf');
            const tabFriend = document.getElementById('tabFriend');
            const unameInput = document.getElementById('targetUsername');
            const tgUser = tgApp?.initDataUnsafe?.user;

            if (mode === 'self') {
                if (tabSelf) tabSelf.classList.add('active');
                if (tabFriend) tabFriend.classList.remove('active');
                if (tgUser && tgUser.username) {
                    unameInput.value = '@' + tgUser.username;
                } else {
                    unameInput.value = '';
                }
            } else {
                if (tabFriend) tabFriend.classList.add('active');
                if (tabSelf) tabSelf.classList.remove('active');
                unameInput.value = '';
                unameInput.focus();
            }
            if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.selectionChanged();
        }

        function openOrderModal(giftId) {
            if (tgApp?.showAlert) {
                tgApp.showAlert("🔧 Hozirda Telegram Sovg'alari (Gift) bo'limida texnik ishlar olib borilmoqda. Xizmat tez orada qayta ishga tushadi!");
            } else {
                alert("🔧 Hozirda Telegram Sovg'alari (Gift) bo'limida texnik ishlar olib borilmoqda. Xizmat tez orada qayta ishga tushadi!");
            }
            if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.notificationOccurred('warning');
            return;
            
            const msgEl = document.getElementById('modalMsg');
            if (msgEl) {
                msgEl.className = 'modal-status-msg';
                msgEl.style.display = 'none';
            }

            document.getElementById('orderModal').classList.add('active');
            if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.impactOccurred('medium');
        }

        function closeOrderModal() {
            document.getElementById('orderModal').classList.remove('active');
            selectedGift = null;
        }

        function closeCelebrationModal() {
            document.getElementById('giftCelebrationModal').classList.remove('active');
        }

        function showCelebrationModal(gift, targetUname) {
            lastPurchasedGift = gift;
            lastPurchasedUsername = targetUname;

            const gName = getGiftName(gift);
            document.getElementById('celebrationImg').src = gift.img;
            document.getElementById('celebrationBadge').textContent = gift.category === 'vip' ? '👑 VIP XARID!' : '🎉 XARID MUBORAK!';
            document.getElementById('celebrationPrizeTitle').textContent = `${gName} (${gift.stars} Stars)`;
            
            if (window.confetti) {
                window.confetti({ particleCount: 150, spread: 90, origin: { y: 0.55 } });
            }
            if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.notificationOccurred('success');

            document.getElementById('giftCelebrationModal').classList.add('active');
        }

        function claimGiftToAdmin() {
            if (!lastPurchasedGift) return;
            const userId = tgApp?.initDataUnsafe?.user?.id || 1;
            const user = tgApp?.initDataUnsafe?.user || {};
            const uname = user.username ? ('@' + user.username) : 'Mavjud emas';
            const name = ((user.first_name || '') + ' ' + (user.last_name || '')).trim() || 'Foydalanuvchi';
            
            const messageText = 
                `Assalomu alaykum! Men CoinStat UZ'dan sovg'a sotib oldim 🎁\n\n` +
                `🎁 Sovg'a: ${lastPurchasedGift.name} (${lastPurchasedGift.stars} Stars)\n` +
                `👤 Xaridor: ${name}\n` +
                `🏷 Username: ${uname}\n` +
                `🎯 Qabul qiluvchi: @${lastPurchasedUsername}\n` +
                `🆔 Telegram ID: ${userId}\n\n` +
                `Iltimos, sovg'amni profilimga yuborishingizni so'rayman!`;

            const adminUrl = `https://t.me/cofeature?text=${encodeURIComponent(messageText)}`;

            if (tgApp && typeof tgApp.openTelegramLink === 'function') {
                tgApp.openTelegramLink(adminUrl);
            } else {
                window.open(adminUrl, '_blank');
            }
        }

        async function submitGiftOrder() {
            if (!selectedGift) return;
            const usernameInput = document.getElementById('targetUsername');
            const rawUsername = (usernameInput.value || '').trim();
            const cleanUsername = rawUsername.replace(/^@/, '');
            const msgEl = document.getElementById('modalMsg');
            const submitBtn = document.getElementById('modalSubmitBtn');

            if (!cleanUsername) {
                if (msgEl) {
                    msgEl.className = 'modal-status-msg error';
                    msgEl.textContent = "Iltimos, Telegram username'ni kiriting!";
                    msgEl.style.display = 'block';
                }
                return;
            }

            submitBtn.disabled = true;
            submitBtn.innerHTML = '<span>⏳ Yuborilmoqda...</span>';

            const userId = tgApp?.initDataUnsafe?.user?.id || (typeof getUserId === 'function' ? getUserId() : 1);
            const apiBase = (typeof getApiBase === 'function' ? getApiBase() : (window.API_BASE || 'https://web-production-4014a4.up.railway.app')) || 'https://web-production-4014a4.up.railway.app';
            const currentGift = selectedGift;
            const endpoint = apiBase.replace(/\/$/, '') + '/api/order/gift';

            try {
                const res = await fetch(endpoint, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tgApp?.initData || '' },
                    body: JSON.stringify({
                        telegram_id: userId,
                        username: cleanUsername,
                        gift: currentGift.id,
                        gift_id: currentGift.id,
                        gift_name: getGiftName(currentGift) || currentGift.name_uz || currentGift.id,
                        amount: currentGift.price,
                        initData: tgApp?.initData || ''
                    })
                });

                let data = null;
                try { data = await res.json(); } catch(e) {}

                if (data && data.ok) {
                    closeOrderModal();
                    if (typeof loadUserBalance === 'function') loadUserBalance();
                    showCelebrationModal(currentGift, cleanUsername);
                } else {
                    const errText = data?.error || "Hisobingizda mablag' yetarli emas yoki xatolik yuz berdi!";
                    if (msgEl) {
                        msgEl.className = 'modal-status-msg error';
                        msgEl.textContent = errText;
                        msgEl.style.display = 'block';
                    }
                    if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.notificationOccurred('error');
                }
            } catch(e) {
                if (msgEl) {
                    msgEl.className = 'modal-status-msg error';
                    msgEl.textContent = "Server bilan aloqa o'rnatilmadi. Iltimos, keyinroq qayta urinib ko'ring!";
                    msgEl.style.display = 'block';
                }
            }

            submitBtn.disabled = false;
            submitBtn.innerHTML = "<span>🎁 Sovg'ani Xarid Qilish</span>";
        }

        // Render immediately
        renderGifts();
        if (typeof loadUserBalance === 'function') loadUserBalance();
        document.addEventListener('DOMContentLoaded', () => {
            renderGifts();
            if (typeof loadUserBalance === 'function') loadUserBalance();
        });

