topup.styles:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
            -webkit-tap-highlight-color: transparent;
        }

        html, body {
            margin: 0;
            padding: 0;
            width: 100%;
            background-color: #0a0a0f;
            background-image: radial-gradient(circle at 50% 0%, #151624 0%, #0a0a0f 65%);
            color: #ffffff;
            overflow-x: hidden;
            box-sizing: border-box;
            scrollbar-width: none;
            -ms-overflow-style: none;
        }

        body {
            padding: 4px 10px 115px 10px;
            min-height: 100vh;
        }

        body::-webkit-scrollbar {
            display: none;
            width: 0;
            height: 0;
        }

        /* Top Bar */
        .topup-top-bar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
            padding: 2px 0;
            transform: translateZ(0);
        }

        .back-pill-btn {
            width: 38px;
            height: 38px;
            border-radius: 12px;
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #ffffff;
            cursor: pointer;
            text-decoration: none;
            transition: transform 120ms ease;
        }

        .back-pill-btn:active {
            transform: scale(0.94);
        }

        .topup-top-title {
            font-size: 16px;
            font-weight: 800;
            color: #ffffff;
            display: flex;
            align-items: center;
            gap: 6px;
            letter-spacing: -0.3px;
        }

        .balance-badge-pill {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            color: #ffffff;
            font-size: 12px;
            font-weight: 700;
            padding: 7px 12px;
            border-radius: 999px;
            display: flex;
            align-items: center;
            gap: 5px;
            white-space: nowrap;
        }

        .balance-badge-pill span {
            color: #38bdf8;
        }

        .lang-badge-pill {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            color: #ffffff;
            font-size: 12px;
            font-weight: 700;
            padding: 7px 11px;
            border-radius: 999px;
            cursor: pointer;
            transition: transform 120ms ease;
        }

        .lang-badge-pill:active {
            transform: scale(0.94);
        }

        /* Step Progress Header */
        .step-indicator-bar {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 16px;
            padding: 12px 14px;
            margin-bottom: 14px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
        }

        .step-badge {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            font-size: 12.5px;
            font-weight: 800;
            color: #38bdf8;
        }

        .step-badge-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: #38bdf8;
            box-shadow: 0 0 8px #38bdf8;
        }

        .step-desc-text {
            font-size: 12px;
            font-weight: 600;
            color: #82879a;
        }

        /* Step Containers */
        .topup-step-container {
            display: none;
            width: 100%;
        }

        .topup-step-container.active {
            display: block;
            animation: fadeInStep 0.2s ease;
        }

        @keyframes fadeInStep {
            from { opacity: 0; transform: translateY(4px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Amount Presets Grid (2x3) */
        .amount-chips-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
            margin-bottom: 12px;
            width: 100%;
        }

        .amount-chip-card {
            background: #1c1c24;
            border: 1.5px solid rgba(255, 255, 255, 0.08);
            border-radius: 16px;
            padding: 14px 6px;
            text-align: center;
            cursor: pointer;
            transition: transform 120ms ease, border-color 150ms ease, background-color 150ms ease;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 3px;
            box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
            user-select: none;
        }

        .amount-chip-card:active {
            transform: scale(0.96);
        }

        .amount-chip-card.selected {
            border-color: #38bdf8;
            background: linear-gradient(135deg, rgba(56, 189, 248, 0.15) 0%, #1c1c24 100%);
            box-shadow: 0 4px 16px rgba(56, 189, 248, 0.25);
        }

        .amount-chip-val {
            font-size: 15px;
            font-weight: 800;
            color: #ffffff;
        }

        .amount-chip-card.selected .amount-chip-val {
            color: #38bdf8;
        }

        .amount-chip-unit {
            font-size: 10px;
            font-weight: 700;
            color: #82879a;
            text-transform: uppercase;
        }

        /* Custom Input Card */
        .custom-amount-card {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 16px;
            padding: 12px 14px;
            margin-bottom: 14px;
            display: flex;
            align-items: center;
            gap: 10px;
            width: 100%;
            box-sizing: border-box;
            transition: border-color 0.2s ease;
            box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
        }

        .custom-amount-card:focus-within {
            border-color: #38bdf8;
        }

        .custom-amount-input {
            background: transparent;
            border: none;
            outline: none;
            color: #ffffff;
            font-size: 14.5px;
            font-weight: 700;
            width: 100%;
        }

        .custom-amount-input::placeholder {
            color: #64748b;
        }

        .custom-amount-currency {
            font-size: 12.5px;
            font-weight: 800;
            color: #38bdf8;
            background: #252633;
            padding: 4px 10px;
            border-radius: 8px;
        }

        /* Buttons */
        .primary-action-btn {
            width: 100%;
            background: linear-gradient(135deg, #38bdf8 0%, #2563eb 100%);
            color: #ffffff;
            border: none;
            border-radius: 16px;
            padding: 14px 18px;
            font-size: 15px;
            font-weight: 800;
            cursor: pointer;
            transition: transform 120ms ease;
            margin-bottom: 14px;
            box-shadow: 0 4px 16px rgba(37, 99, 235, 0.35);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .primary-action-btn:active {
            transform: scale(0.97);
        }

        .secondary-back-btn {
            width: 100%;
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            color: #94a3b8;
            border-radius: 16px;
            padding: 12px;
            font-size: 13.5px;
            font-weight: 700;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            margin-bottom: 14px;
            transition: transform 120ms ease;
        }

        .secondary-back-btn:active {
            transform: scale(0.97);
            color: #ffffff;
        }

        /* STEP 2 SPECIFIC STYLES */
        /* 5-Minute Timer Banner */
        .timer-banner-card {
            background: #1c1c24;
            border: 1px solid rgba(245, 158, 11, 0.3);
            border-radius: 16px;
            padding: 12px 14px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
            width: 100%;
