            align-items: center;
            gap: 10px;
        }

        .timer-info-text {
            font-size: 13px;
            font-weight: 800;
            color: #ffffff;
        }

        .timer-sub-hint {
            font-size: 11px;
            color: #fbbf24;
            font-weight: 600;
        }

        .timer-digits-box {
            font-size: 20px;
            font-weight: 900;
            color: #fbbf24;
            font-variant-numeric: tabular-nums;
            letter-spacing: 0.5px;
            background: #252633;
            padding: 4px 10px;
            border-radius: 10px;
        }

        /* Exact Amount Box */
        .pay-amount-highlight-box {
            background: #1c1c24;
            border: 1.5px solid rgba(56, 189, 248, 0.3);
            border-radius: 16px;
            padding: 14px 16px;
            margin-bottom: 12px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            box-sizing: border-box;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
        }

        .pay-label-title {
            font-size: 13px;
            font-weight: 700;
            color: #82879a;
        }

        .pay-value-badge {
            font-size: 18px;
            font-weight: 900;
            color: #38bdf8;
        }

        /* 3D Bank Card */
        .credit-card {
            background: linear-gradient(135deg, #181926 0%, #12131c 100%);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 20px;
            padding: 18px 16px;
            margin-bottom: 12px;
            position: relative;
            overflow: hidden;
            width: 100%;
            box-sizing: border-box;
            box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
        }

        .card-top-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 14px;
        }

        .chip-icon {
            width: 32px;
            height: 24px;
            background: linear-gradient(135deg, #fbbf24 0%, #d97706 100%);
            border-radius: 6px;
        }

        .card-status-badge {
            background: rgba(255, 255, 255, 0.15);
            border: 1px solid rgba(255, 255, 255, 0.3);
            color: #ffffff;
            font-size: 13px;
            font-weight: 900;
            font-style: italic;
            padding: 3px 12px;
            border-radius: 999px;
            letter-spacing: 1px;
        }

        .card-number-wrapper {
            margin-bottom: 14px;
            cursor: pointer;
        }

        .card-label-small {
            font-size: 10.5px;
            font-weight: 700;
            color: #82879a;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 4px;
        }

        .card-number-display {
            font-size: 19px;
            font-weight: 900;
            color: #ffffff;
            letter-spacing: 1.5px;
            font-variant-numeric: tabular-nums;
        }

        .card-bottom-row {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
        }

        .card-holder-name {
            font-size: 13.5px;
            font-weight: 800;
            color: #f1f5f9;
            text-transform: uppercase;
        }

        .copy-pill-button {
            background: linear-gradient(135deg, #38bdf8 0%, #2563eb 100%);
            color: #ffffff;
            border: none;
            border-radius: 10px;
            padding: 7px 14px;
            font-size: 12px;
            font-weight: 800;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 5px;
            transition: transform 120ms ease;
            box-shadow: 0 2px 10px rgba(37, 99, 235, 0.3);
        }

        .copy-pill-button:active {
            transform: scale(0.94);
        }

        /* Instruction Notice */
        .instruction-notice-box {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 14px;
            padding: 12px 14px;
            margin-bottom: 14px;
            font-size: 12px;
            color: #94a3b8;
            line-height: 1.45;
            display: flex;
            align-items: flex-start;
            gap: 8px;
            width: 100%;
            box-sizing: border-box;
        }

        .instruction-notice-box svg {
            color: #38bdf8;
            flex-shrink: 0;
            margin-top: 2px;
        }

        /* Help Box */
        .topup-help-box {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 16px;
            padding: 14px;
            text-align: center;
            margin-bottom: 16px;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            width: 100%;
            box-sizing: border-box;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
        }

        .topup-help-text {
            font-size: 12px;
            color: #82879a;
            font-weight: 600;
        }

        .topup-admin-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            background: #252633;
            border: 1px solid rgba(255, 255, 255, 0.1);
            color: #ffffff;
            padding: 10px 16px;
            border-radius: 12px;
            font-size: 13px;
            font-weight: 700;
            text-decoration: none;
            width: 100%;
            box-sizing: border-box;
            transition: transform 120ms ease;
        }

        .topup-admin-btn:active {
            transform: scale(0.98);
            background: #2e2f3e;
        }

        /* Toast notification */
        .copy-toast {
            position: fixed;
            top: 20px;
            left: 50%;
            transform: translateX(-50%) translateY(-100px);
            background: #1c1c24;
            color: #38bdf8;
            border: 1px solid #38bdf8;
            padding: 10px 20px;
            border-radius: 999px;
            font-size: 13px;
