topup.script:
let selectedAmount = 25000;
        let countdownTimer = null;
        let timeLeftSeconds = 300; // 5 minutes = 300 seconds

        function updateCtaPrice(val) {
            const el = document.getElementById('ctaPriceText');
            if (el) el.textContent = val ? val.toLocaleString('uz-UZ') : '0';
        }

        function selectAmount(val, el) {
            selectedAmount = val;
            document.querySelectorAll('.amount-chip-card').forEach(c => c.classList.remove('selected'));
            if (el) el.classList.add('selected');
            document.getElementById('customAmountInput').value = '';
            updateCtaPrice(val);
            if (tg && tg.HapticFeedback) tg.HapticFeedback.selectionChanged();
        }

        function onCustomAmountInput() {
            const val = parseInt(document.getElementById('customAmountInput').value, 10);
            if (val && val > 0) {
                selectedAmount = val;
                document.querySelectorAll('.amount-chip-card').forEach(c => c.classList.remove('selected'));
                updateCtaPrice(val);
            } else {
                selectedAmount = 0;
                updateCtaPrice(0);
            }
        }

        function proceedToPaymentStep() {
            if (!selectedAmount || selectedAmount < 1000) {
                if (tg && tg.showAlert) tg.showAlert('Iltimos, kamida 1,000 so\'m summa kiriting.');
                else alert('Iltimos, kamida 1,000 so\'m summa kiriting.');
                return;
            }

            const formatted = selectedAmount.toLocaleString('uz-UZ') + ' UZS';
            const sumEl = document.getElementById('summaryAmountText');
            if (sumEl) sumEl.textContent = formatted;

            const stepBadge = document.getElementById('stepBadgeText');
            const stepSubEl = document.getElementById('stepSubtext');
            if (stepBadge) stepBadge.textContent = '2-QADAM';
            if (stepSubEl) {
                const lang = localStorage.getItem('starpay_lang') || 'uz';
                if (lang === 'ru') stepSubEl.textContent = 'Оплатите на карту и подтвердите';
                else if (lang === 'en') stepSubEl.textContent = 'Transfer to card & confirm';
                else stepSubEl.textContent = 'Kartaga to\'lov qiling va tasdiqlang';
            }

            const s1 = document.getElementById('step1Container');
            const s2 = document.getElementById('step2Container');
            if (s1) s1.classList.remove('active');
            if (s2) s2.classList.add('active');

            if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred('success');

            startPaymentTimer();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        function backToStep1() {
            clearInterval(countdownTimer);
            const s1 = document.getElementById('step1Container');
            const s2 = document.getElementById('step2Container');
            if (s2) s2.classList.remove('active');
            if (s1) s1.classList.add('active');

            const stepBadge = document.getElementById('stepBadgeText');
            const stepSubEl = document.getElementById('stepSubtext');
            if (stepBadge) stepBadge.textContent = '1-QADAM';
            if (stepSubEl) {
                const lang = localStorage.getItem('starpay_lang') || 'uz';
                if (lang === 'ru') stepSubEl.textContent = 'Выберите сумму пополнения';
                else if (lang === 'en') stepSubEl.textContent = 'Select top-up amount';
                else stepSubEl.textContent = 'Kerakli to\'lov summasini tanlang';
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        function startPaymentTimer() {
            clearInterval(countdownTimer);
            timeLeftSeconds = 300; // 5 minutes
            updateTimerDisplay();

            countdownTimer = setInterval(() => {
                timeLeftSeconds--;
                if (timeLeftSeconds <= 0) {
                    clearInterval(countdownTimer);
                    document.getElementById('timerDisplay').textContent = '00:00';
                    if (tg && tg.showAlert) {
                        tg.showAlert('⚠️ To\'lov uchun berilgan 5 daqiqa vaqt tugadi. Agar to\'lagan bo\'lsangiz, baribir tugmani bosing yoki qaytadan urinib ko\'ring.');
                    }
                } else {
                    updateTimerDisplay();
                }
            }, 1000);
        }

        function updateTimerDisplay() {
            const minutes = Math.floor(timeLeftSeconds / 60);
            const seconds = timeLeftSeconds % 60;
            const text = String(minutes).padStart(2, '0') + ':' + String(seconds).padStart(2, '0');
            const el = document.getElementById('timerDisplay');
            if (el) el.textContent = text;
        }

        function showCopyToast() {
            const toast = document.getElementById('copyToast');
            if (toast) {
                toast.classList.add('show');
                setTimeout(() => toast.classList.remove('show'), 2000);
            }
        }

        function copyCardNumber() {
            const num = document.getElementById('cardNumberText').textContent.replace(/\s+/g, '');
            if (navigator.clipboard) {
                navigator.clipboard.writeText(num);
                showCopyToast();
                if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred('success');
            } else {
                const el = document.createElement('textarea');
                el.value = num;
                document.body.appendChild(el);
                el.select();
                document.execCommand('copy');
                document.body.removeChild(el);
                showCopyToast();
            }
        }

        let isTopupSubmitting = false;

        async function submitTopup() {
            if (isTopupSubmitting) return; // Prevent duplicate requests on multiple clicks!

            const userId = getUserId();
            const apiBase = getApiBase();
            const orderId = 'TOP_' + Date.now();

            if (!selectedAmount || selectedAmount < 1000) {
                if (tg && tg.showAlert) tg.showAlert('Iltimos, to\'g\'ri summa kiriting (kamida 1,000 so\'m)');
                else alert('Iltimos, to\'g\'ri summa kiriting (kamida 1,000 so\'m)');
                return;
            }

            isTopupSubmitting = true;
            const btn = document.getElementById('submitBtn');
            const oldHtml = btn.innerHTML;
            btn.disabled = true;
            btn.style.pointerEvents = 'none';
            btn.style.opacity = '0.7';
            btn.innerHTML = '<span>⏳</span> Yuborildi, tekshirilmoqda...';

            try {
                const tgUser = tg?.initDataUnsafe?.user;
                const uname = tgUser?.username ? ('@' + tgUser.username.replace('@', '')) : '';
                const uFullName = [tgUser?.first_name, tgUser?.last_name].filter(Boolean).join(' ');
                const apiBase = (typeof getApiBase === 'function' ? getApiBase() : (window.API_BASE || 'https://web-production-4014a4.up.railway.app')) || 'https://web-production-4014a4.up.railway.app';
                const endpoint = apiBase.replace(/\/$/, '') + '/api/order/topup';

                const res = await fetch(endpoint, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': (tg && tg.initData) ? tg.initData : '' },
                    body: JSON.stringify({
                        order_id: orderId,
                        telegram_id: userId,
                        user_id: userId,
                        username: uname,
                        first_name: tgUser?.first_name || '',
                        name: uFullName,
                        amount: selectedAmount,
                        payment_method: 'card',
                        initData: (tg && tg.initData) ? tg.initData : ''
                    })
                });

                let data = null;
                try {
                    data = await res.json();
                } catch (jsonErr) {}

                if (data && data.ok) {
                    clearInterval(countdownTimer);
                    if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred('success');
                    if (tg && tg.showAlert) {
                        tg.showAlert(`✅ ${selectedAmount.toLocaleString('uz-UZ')} so'mlik to'lov so'rovingiz qabul qilindi! Admin tekshirib, hisobingizga balans qo'shadi.`);
                    } else {
                        alert(`✅ ${selectedAmount.toLocaleString('uz-UZ')} so'mlik to'lov so'rovingiz qabul qilindi!`);
                    }
                    setTimeout(() => window.location.href = 'orders.html', 1000);
                } else if (res.ok || (data && data.order_id)) {
                    clearInterval(countdownTimer);
                    if (tg && tg.showAlert) {
                        tg.showAlert(`✅ To'lov so'rovingiz qabul qilindi! Admin tekshirib, hisobingizga balans qo'shadi.`);
                    } else {
                        alert(`✅ To'lov so'rovingiz qabul qilindi!`);
                    }
                    setTimeout(() => window.location.href = 'orders.html', 1000);
                } else {
                    const err = data?.error || 'To\'lov so\'rovini yuborishda xatolik yuz berdi. Iltimos adminga murojaat qiling.';
                    if (tg && tg.showAlert) tg.showAlert(err);
                    else alert(err);
                    isTopupSubmitting = false;
                    btn.disabled = false;
                    btn.style.pointerEvents = 'auto';
                    btn.style.opacity = '1';
                    btn.innerHTML = oldHtml;
                }
            } catch (err) {
                if (tg && tg.showAlert) tg.showAlert('Xatolik: ' + err.message);
                else alert('Xatolik: ' + err.message);
                isTopupSubmitting = false;
                btn.disabled = false;
                btn.style.pointerEvents = 'auto';
                btn.style.opacity = '1';
                btn.innerHTML = oldHtml;
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            loadUserBalance();
            updateCtaPrice(selectedAmount);
        });

