orders.script:
let allOrders = [];

        async function fetchOrders() {
            const userId = getUserId();
            const apiBase = getApiBase();
            const container = document.getElementById('ordersList');

            if (!userId) {
                container.innerHTML = '<div class="empty-state">Foydalanuvchi aniqlanmadi</div>';
                return;
            }

            try {
                const res = await fetch((apiBase ? apiBase : '') + '/api/user/transactions', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg.initData || '' },
                    body: JSON.stringify({ telegram_id: userId, initData: tg.initData || '' })
                });
                const data = await res.json();
                if (data && data.ok) {
                    allOrders = data.orders || [];
                    updateStats(allOrders);
                    renderOrders(allOrders);
                } else {
                    container.innerHTML = '<div class="empty-state">Buyurtmalar topilmadi</div>';
                }
            } catch (err) {
                container.innerHTML = '<div class="empty-state">Yuklashda xatolik yuz berdi</div>';
            }
        }

        function updateStats(orders) {
            const purchaseOrders = (orders || []).filter(o => {
                const pt = String(o.product_type || o.type || '').toLowerCase();
                return !pt.startsWith('topup') && pt !== 'deposit' && pt !== 'balance';
            });
            document.getElementById('statAll').textContent = purchaseOrders.length;
            document.getElementById('statDone').textContent = purchaseOrders.filter(o => o.status === 'completed' || o.status === 'paid').length;
            document.getElementById('statPending').textContent = purchaseOrders.filter(o => o.status === 'pending').length;
        }

        function filterOrders(type, btn) {
            document.querySelectorAll('.filter-chip-btn').forEach(b => b.classList.remove('active'));
            if (btn) btn.classList.add('active');

            if (type === 'all') {
                renderOrders(allOrders);
            } else {
                const filtered = allOrders.filter(o => {
                    const ptype = (o.product_type || o.type || '').toLowerCase();
                    return ptype.includes(type);
                });
                renderOrders(filtered);
            }
        }

        function renderOrders(orders) {
            const container = document.getElementById('ordersList');
            if (!orders || orders.length === 0) {
                container.innerHTML = '<div class="empty-state">Hozircha hech qanday buyurtma yo\'q</div>';
                return;
            }

            const typeNames = {
                stars: '⭐ Telegram Stars',
                premium: '💎 Telegram Premium',
                gift: '🎁 Telegram Gift',
                phone: '📱 Virtual Raqam',
                topup: '💳 Hisob To\'ldirish',
                deposit: '💳 Hisob To\'ldirish',
            };

            let html = '';
            orders.forEach(o => {
                const st = (o.status || 'completed').toLowerCase();
                let stLabel = 'Bajarildi';
                let stClass = 'completed';
                if (st === 'pending') { stLabel = 'Kutilmoqda'; stClass = 'pending'; }
                else if (st === 'rejected' || st === 'cancelled') { stLabel = 'Bekor qilindi'; stClass = 'rejected'; }

                const rawType = (o.product_type || o.type || 'xarid').toLowerCase();
                const typeTitle = typeNames[rawType] || (rawType.charAt(0).toUpperCase() + rawType.slice(1));
                const targetUser = o.target_username ? ` · @${o.target_username.replace(/^@/, '')}` : '';
                const qtyText = (rawType === 'stars' && o.quantity) ? ` (${o.quantity} ⭐)` : (rawType === 'premium' && o.quantity) ? ` (${o.quantity} oy)` : '';
                const amount = Number(o.amount || o.price || 0).toLocaleString('uz-UZ') + " UZS";
                const dateStr = o.created_at ? new Date(o.created_at).toLocaleString('uz-UZ') : 'Yaqinda';

                html += `
                    <div class="order-item-card">
                        <div class="order-card-header">
                            <div class="order-type-title">${typeTitle}${qtyText}</div>
                            <div class="order-status-badge ${stClass}">${stLabel}</div>
                        </div>
                        <div class="order-card-body">
                            <div class="order-date-text">${dateStr}${targetUser}</div>
                            <div class="order-amount-text">${amount}</div>
                        </div>
                    </div>
                `;
            });

            container.innerHTML = html;
        }

        document.addEventListener('DOMContentLoaded', fetchOrders);

