profile.script:
document.addEventListener('DOMContentLoaded', () => {
            loadUserBalance();
            fetchTransactions();
            initToggleState();

            if (tg?.initDataUnsafe?.user?.photo_url) {
                const av = document.getElementById('profileAvatar');
                if (av) av.src = tg.initDataUnsafe.user.photo_url;
            }
        });

        function initToggleState() {
            const toggle = document.getElementById('animationToggle');
            if (toggle) {
                const isLite = localStorage.getItem('coinstat_disable_animations') === 'true';
                toggle.checked = isLite;
            }
        }

        function onAnimationToggleChange(checkbox) {
            toggleAnimations(checkbox.checked);
            if (tg && tg.HapticFeedback) {
                tg.HapticFeedback.selectionChanged();
            }
        }

        async function fetchTransactions() {
            const userId = getUserId();
            const apiBase = getApiBase();
            if (!userId) return;

            try {
                const res = await fetch((apiBase ? apiBase : '') + '/api/user/transactions', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg?.initData || '' },
                    body: JSON.stringify({ telegram_id: userId, initData: tg?.initData || '' })
                });
                const data = await res.json();
                if (data && data.ok) {
                    const purchaseOrders = (data.orders || []).filter(o => {
                        const pt = String(o.product_type || o.type || '').toLowerCase();
                        return !pt.startsWith('topup') && 
                               pt !== 'deposit' && 
                               pt !== 'balance' &&
                               o.status !== 'cancelled' &&
                               o.status !== 'failed' &&
                               o.status !== 'rejected';
                    });

                    const ordersCount = (typeof data.orders_count === 'number') ? data.orders_count : purchaseOrders.length;
                    document.querySelectorAll('#ordersCount, #profileOrdersCount, .live-orders-count').forEach(el => {
                        el.textContent = String(ordersCount);
                    });

                    let totalSpent = 0;
                    if (typeof data.total_spent === 'number') {
                        totalSpent = data.total_spent;
                    } else {
                        purchaseOrders.forEach(o => {
                            if (o.status === 'completed' || o.status === 'paid') {
                                totalSpent += Number(o.amount || 0);
                            }
                        });
                    }

                    let formattedSpent = '0';
                    if (totalSpent >= 1000000) {
                        const m = (totalSpent / 1000000);
                        formattedSpent = (m % 1 === 0 ? m.toFixed(0) : m.toFixed(1)) + 'M';
                    } else if (totalSpent >= 1000) {
                        const k = (totalSpent / 1000);
                        formattedSpent = (k % 1 === 0 ? k.toFixed(0) : k.toFixed(1)) + 'k';
                    } else {
                        formattedSpent = totalSpent.toLocaleString('uz-UZ');
                    }

                    document.querySelectorAll('#totalSpent, #profileTotalSpent, .live-total-spent').forEach(el => {
                        el.textContent = formattedSpent;
                    });

                    const uidKey = (typeof getUserId === 'function' ? getUserId() : null) || 'guest';
                    try {
                        localStorage.setItem('cs_stat_orders_' + uidKey, String(ordersCount));
                        localStorage.setItem('cs_stat_spent_' + uidKey, formattedSpent);
                    } catch(e) {}
                }
            } catch (e) {}
        }

