rating.script:
let cachedRatingList = [];

        function switchPeriod(period, btn) {
            document.querySelectorAll('.period-tab-btn').forEach(b => b.classList.remove('active'));
            if (btn) btn.classList.add('active');
            if (tg && tg.HapticFeedback) tg.HapticFeedback.selectionChanged();
            loadRatingData(period);
        }

        async function loadRatingData(period = 'week') {
            const apiBase = getApiBase();
            const currentUserId = String(getUserId() || '');

            try {
                const res = await fetch((apiBase ? apiBase : '') + '/api/rating', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg?.initData || '' },
                    body: JSON.stringify({ period: period, initData: tg?.initData || '' })
                });
                const data = await res.json();
                const list = (data && data.ok && Array.isArray(data.rating)) ? data.rating : [];
                cachedRatingList = list;
                renderPodiumAndList(list, currentUserId);
            } catch (err) {
                cachedRatingList = [];
                renderPodiumAndList([], currentUserId);
            }
        }

        function getAvatarUrl(item, currentUserId) {
            if (!item) return './images/logo.webp?v=3';
            const tgUser = tg?.initDataUnsafe?.user;
            const rawUsername = String(item.username || '').replace(/^@/, '').toLowerCase();
            const tgUsername = String(tgUser?.username || '').replace(/^@/, '').toLowerCase();
            const isMe = (String(item.telegram_id) === String(currentUserId)) || (tgUsername && rawUsername === tgUsername);

            if (isMe && tgUser?.photo_url) {
                return tgUser.photo_url;
            }
            if (item.photo_url) return item.photo_url;
            if (item.avatar_url) return item.avatar_url;

            const letter = (item.username || item.full_name || 'U').replace(/^@/, '')[0]?.toUpperCase() || 'U';
            const colors = ['2563eb', '7c3aed', 'db2777', 'ea580c', '059669', '0284c7'];
            const color = colors[Math.abs(Number(item.telegram_id || 0)) % colors.length] || '2563eb';
            return `https://ui-avatars.com/api/?name=${encodeURIComponent(letter)}&background=${color}&color=fff&bold=true&rounded=true&size=128`;
        }

        function openUserProfile(rank, username, amountFormatted, avatarUrl, fullName) {
            if (!username && !amountFormatted) return;
            if (tg && tg.HapticFeedback) tg.HapticFeedback.impactOccurred('light');

            const overlay = document.getElementById('userModalOverlay');
            const avatarEl = document.getElementById('modalAvatarImg');
            const rankBadgeEl = document.getElementById('modalRankBadge');
            const nameEl = document.getElementById('modalUserName');
            const handleEl = document.getElementById('modalUserHandle');
            const statRankEl = document.getElementById('modalStatRank');
            const statTurnoverEl = document.getElementById('modalStatTurnover');
            const tgLinkBtn = document.getElementById('modalTgLink');

            avatarEl.src = avatarUrl || './images/logo.webp?v=3';
            rankBadgeEl.textContent = rank ? `#${rank}` : '—';
            statRankEl.textContent = rank ? `#${rank} O'rin` : '—';
            statTurnoverEl.textContent = amountFormatted || '0 UZS';

            const rawUser = String(username || '').replace(/^@/, '');
            nameEl.textContent = fullName || (rawUser ? '@' + rawUser : 'Foydalanuvchi');
            handleEl.textContent = rawUser ? '@' + rawUser : 'Telegram foydalanuvchisi';

            if (rawUser) {
                tgLinkBtn.style.display = 'flex';
                tgLinkBtn.href = `https://t.me/${rawUser}`;
            } else {
                tgLinkBtn.style.display = 'none';
            }

            if (overlay) overlay.classList.add('active');
        }

        function closeUserProfile(e) {
            const overlay = document.getElementById('userModalOverlay');
            if (overlay) overlay.classList.remove('active');
        }

        function renderPodiumAndList(list, currentUserId) {
            const container = document.getElementById('leaderboardList');
            const av1 = document.getElementById('podiumAvatar1');
            const av2 = document.getElementById('podiumAvatar2');
            const av3 = document.getElementById('podiumAvatar3');
            const myAv = document.getElementById('myAvatarImg');

            if (myAv && tg?.initDataUnsafe?.user?.photo_url) {
                myAv.src = tg.initDataUnsafe.user.photo_url;
            }

            // 1st Place (Center)
            const p1 = document.getElementById('podium1');
            if (list[0] && Number(list[0].total) > 0) {
                const u1 = (list[0].username || 'User#' + list[0].telegram_id);
                const amt1 = Number(list[0].total).toLocaleString('uz-UZ') + ' UZS';
                const avatar1 = getAvatarUrl(list[0], currentUserId);
                document.getElementById('podiumUser1').textContent = '@' + u1.replace(/^@/, '');
                document.getElementById('podiumAmount1').textContent = amt1;
                p1.style.opacity = '1';
                if (av1) av1.src = avatar1;
                p1.onclick = () => openUserProfile(1, u1, amt1, avatar1, list[0].full_name);
            } else {
                document.getElementById('podiumUser1').textContent = '—';
                document.getElementById('podiumAmount1').textContent = '0 UZS';
                p1.style.opacity = '0.7';
                if (av1) av1.src = './images/logo.webp?v=3';
                p1.onclick = null;
            }

            // 2nd Place (Left)
            const p2 = document.getElementById('podium2');
            if (list[1] && Number(list[1].total) > 0) {
                const u2 = (list[1].username || 'User#' + list[1].telegram_id);
                const amt2 = Number(list[1].total).toLocaleString('uz-UZ') + ' UZS';
                const avatar2 = getAvatarUrl(list[1], currentUserId);
                document.getElementById('podiumUser2').textContent = '@' + u2.replace(/^@/, '');
                document.getElementById('podiumAmount2').textContent = amt2;
                p2.style.opacity = '1';
                if (av2) av2.src = avatar2;
                p2.onclick = () => openUserProfile(2, u2, amt2, avatar2, list[1].full_name);
            } else {
                document.getElementById('podiumUser2').textContent = '—';
                document.getElementById('podiumAmount2').textContent = '0 UZS';
                p2.style.opacity = '0.7';
                if (av2) av2.src = './images/logo.webp?v=3';
                p2.onclick = null;
            }

            // 3rd Place (Right)
            const p3 = document.getElementById('podium3');
            if (list[2] && Number(list[2].total) > 0) {
                const u3 = (list[2].username || 'User#' + list[2].telegram_id);
                const amt3 = Number(list[2].total).toLocaleString('uz-UZ') + ' UZS';
                const avatar3 = getAvatarUrl(list[2], currentUserId);
                document.getElementById('podiumUser3').textContent = '@' + u3.replace(/^@/, '');
                document.getElementById('podiumAmount3').textContent = amt3;
                p3.style.opacity = '1';
                if (av3) av3.src = avatar3;
                p3.onclick = () => openUserProfile(3, u3, amt3, avatar3, list[2].full_name);
            } else {
                document.getElementById('podiumUser3').textContent = '—';
                document.getElementById('podiumAmount3').textContent = '0 UZS';
                p3.style.opacity = '0.7';
                if (av3) av3.src = './images/logo.webp?v=3';
                p3.onclick = null;
            }

            // Remaining list rows (from #4 onwards)
            let html = '';
            let myRank = null;
            let myTurnover = 0;

            list.forEach((item, i) => {
                const rank = i + 1;
                const rawUsername = (item.username || '').replace(/^@/, '');
                const uname = rawUsername ? '@' + rawUsername : 'User#' + (item.telegram_id || (i + 1));
                const totalVal = Number(item.total || 0);
                const totalFormatted = totalVal.toLocaleString('uz-UZ') + ' UZS';
                const rowAvatar = getAvatarUrl(item, currentUserId);
                const fullNameSafe = (item.full_name || '').replace(/'/g, "\\'");

                const tgUsername = (tg?.initDataUnsafe?.user?.username || '').replace(/^@/, '');
                if (String(item.telegram_id) === currentUserId || (tgUsername && rawUsername.toLowerCase() === tgUsername.toLowerCase())) {
                    myRank = rank;
                    myTurnover = totalVal;
                }

                if (rank > 3 && totalVal > 0) {
                    html += `
                        <div class="leader-row-card" onclick="openUserProfile(${rank}, '${rawUsername}', '${totalFormatted}', '${rowAvatar}', '${fullNameSafe}')">
                            <div class="leader-row-left">
                                <div class="leader-row-rank">#${rank}</div>
                                <div class="leader-row-avatar">
                                    <img src="${rowAvatar}" alt="${uname}" onerror="this.src='./images/logo.webp?v=3'">
                                </div>
                                <div class="leader-row-info">
                                    <div class="leader-row-username">${uname}</div>
                                    <div class="leader-row-tag">🔥 Faol Xaridor</div>
                                </div>
                            </div>
                            <div class="leader-row-right">
                                <div class="leader-row-turnover-val">${totalFormatted}</div>
                                <div class="leader-row-turnover-label">Aylanma</div>
                            </div>
                        </div>
                    `;
                }
            });

            if (list.length === 0) {
                html = `
                    <div style="text-align: center; padding: 28px 16px; color: #82879a; font-size: 13px; font-weight: 700; background: #1c1c24; border-radius: 18px; border: 1px dashed rgba(255,255,255,0.08); box-shadow: 0 4px 14px rgba(0,0,0,0.25);">
                        🛍 Hozircha bu davrda xaridlar yo'q.<br><span style="color: #38bdf8; font-weight: 800; display: inline-block; margin-top: 4px;">Birinchi bo'lib xarid qiling va 1-o'rinni egallang!</span>
                    </div>
                `;
            }

            container.innerHTML = html;

            const myRankEl = document.getElementById('myRankNum');
            const myTurnoverEl = document.getElementById('myTurnoverVal');
            const myRankDock = document.getElementById('myRankDock');

            const setRankUI = (rank, turnover) => {
                if (myRankEl) {
                    if (rank) myRankEl.textContent = `#${rank}`;
                    else if (turnover > 0) myRankEl.textContent = '#1';
                    else myRankEl.textContent = '—';
                }
                if (myTurnoverEl) {
                    myTurnoverEl.textContent = turnover > 0 ? Number(turnover).toLocaleString('uz-UZ') + ' UZS' : '0 UZS';
                }
                if (myRankDock) {
                    const myUname = tg?.initDataUnsafe?.user?.username || 'Men';
                    const myFullName = (tg?.initDataUnsafe?.user?.first_name || '') + ' ' + (tg?.initDataUnsafe?.user?.last_name || '');
                    const myPhoto = tg?.initDataUnsafe?.user?.photo_url || './images/logo.webp?v=3';
                    const formattedTurnover = turnover > 0 ? Number(turnover).toLocaleString('uz-UZ') + ' UZS' : '0 UZS';
                    myRankDock.onclick = () => openUserProfile(rank, myUname, formattedTurnover, myPhoto, myFullName.trim());
                }
            };

            setRankUI(myRank, myTurnover);

            // Fetch personal spent turnover from transactions if not determined
            const apiBase = getApiBase();
            if (currentUserId && !myRank) {
                fetch((apiBase ? apiBase : '') + '/api/user/transactions', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg?.initData || '' },
                    body: JSON.stringify({ telegram_id: currentUserId, initData: tg?.initData || '' })
                }).then(r => r.json()).then(tData => {
                    if (tData && tData.ok && typeof tData.total_spent === 'number') {
                        if (tData.total_spent > 0) {
                            myTurnover = tData.total_spent;
                            setRankUI(myRank || (list.length === 0 ? 1 : null), myTurnover);
                        }
                    }
                }).catch(() => {});
            }

            if (tg?.initDataUnsafe?.user?.photo_url) {
                const myAv = document.getElementById('myAvatarImg');
                if (myAv) myAv.src = tg.initDataUnsafe.user.photo_url;
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            loadUserBalance();
            loadRatingData('week');
        });

spin.styles:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
            -webkit-tap-highlight-color: transparent;
        }

        :root {
            --primary-gradient: linear-gradient(135deg, #38bdf8 0%, #2563eb 100%);
            --gold-gradient: linear-gradient(135deg, #fbbf24 0%, #d97706 100%);
            --gold-glow: rgba(245, 158, 11, 0.35);
            --wheel-border: #f59e0b;
            --glass-bg: rgba(20, 21, 29, 0.85);
            --glass-border: rgba(255, 255, 255, 0.08);
        }

        body {
            background-color: #08080c;
            background-image: 
                radial-gradient(circle at 50% 15%, rgba(245, 158, 11, 0.15) 0%, transparent 50%),
                radial-gradient(circle at 10% 40%, rgba(56, 189, 248, 0.08) 0%, transparent 45%),
                radial-gradient(circle at 90% 70%, rgba(168, 85, 247, 0.08) 0%, transparent 45%);
            color: #ffffff;
            padding: 16px;
            padding-bottom: 120px;
            min-height: 100vh;
            overflow-x: hidden;
        }

        /* Top Bar */
        .spin-top-bar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 16px;
            padding: 2px 0;
            width: 100%;
        }

        .back-pill-btn {
            width: 40px;
            height: 40px;
            border-radius: 14px;
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #ffffff;
            cursor: pointer;
            transition: transform 120ms ease, background-color 120ms ease;
            user-select: none;
            flex-shrink: 0;
        }

        .back-pill-btn:active {
            transform: scale(0.94);
            background: #272733;
        }

        .balance-pill-badge {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            color: #38bdf8;
            font-size: 13px;
            font-weight: 800;
            padding: 8px 14px;
            border-radius: 999px;
            letter-spacing: -0.2px;
            white-space: nowrap;
        }

        .lang-badge-pill {
            background: #1c1c24;
            border: 1px solid rgba(255, 255, 255, 0.08);
            color: #94a3b8;
            font-size: 12px;
            font-weight: 700;
            padding: 8px 12px;
            border-radius: 999px;
            cursor: pointer;
            text-transform: uppercase;
            transition: transform 120ms ease, background-color 120ms ease;
            user-select: none;
            flex-shrink: 0;
        }

        .lang-badge-pill:active {
            transform: scale(0.94);
            background: #272733;
        }

        /* Page Heading */
        .page-header-wrap {
            text-align: center;
            margin-bottom: 16px;
        }

        .spin-page-heading {
            font-size: 26px;
            font-weight: 900;
            color: #ffffff;
            letter-spacing: -0.8px;
            line-height: 1.2;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .spin-page-subtext {
            font-size: 13px;
            color: #94a3b8;
            margin-top: 4px;
            font-weight: 600;
        }

        /* Promocode Voucher & Status Card */
        .promo-voucher-card {
            background: linear-gradient(135deg, rgba(30, 27, 75, 0.65) 0%, rgba(20, 21, 29, 0.95) 100%);
            border: 1px solid rgba(168, 85, 247, 0.35);
            border-radius: 22px;
            padding: 16px 18px;
            margin-bottom: 22px;
            backdrop-filter: blur(12px);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
            box-sizing: border-box;
            width: 100%;
            overflow: hidden;
        }

        .top-status-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            margin-bottom: 12px;
        }

        .top-status-left {
            display: flex;
            align-items: center;
            gap: 10px;
            min-width: 0;
        }

        .top-status-icon {
            font-size: 24px;
            flex-shrink: 0;
        }

        .top-status-title {
            font-size: 13.5px;
            font-weight: 800;
            color: #ffffff;
            line-height: 1.2;
        }

        .top-status-desc {
            font-size: 11px;
            color: #94a3b8;
            font-weight: 600;
            margin-top: 2px;
            line-height: 1.25;
        }

        .top-status-badge {
            font-size: 11.5px;
            font-weight: 800;
            padding: 5px 11px;
            border-radius: 999px;
            white-space: nowrap;
            flex-shrink: 0;
        }

        .badge-eligible {
            background: rgba(34, 197, 94, 0.15);
            border: 1px solid rgba(34, 197, 94, 0.4);
            color: #4ade80;
        }

        .badge-locked {
            background: rgba(239, 68, 68, 0.15);
            border: 1px solid rgba(239, 68, 68, 0.4);
            color: #f87171;
        }

        /* Live Countdown Digital Card */
        .countdown-timer-card {
            background: linear-gradient(135deg, rgba(245, 158, 11, 0.08) 0%, rgba(20, 21, 29, 0.9) 100%);
            border: 1px solid rgba(251, 191, 36, 0.35);
            border-radius: 20px;
            padding: 16px;
            margin-bottom: 20px;
            text-align: center;
            backdrop-filter: blur(12px);
            box-shadow: 0 8px 24px rgba(245, 158, 11, 0.15);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 10px;
        }

        .countdown-header-tag {
            font-size: 11px;
            font-weight: 800;
            letter-spacing: 1px;
            color: #fbbf24;
            display: flex;
            align-items: center;
            gap: 6px;
            text-transform: uppercase;
        }

        .countdown-clock-row {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .clock-digit-box {
            background: #11121a;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 14px;
            padding: 10px 14px;
            min-width: 62px;
            display: flex;
            flex-direction: column;
            align-items: center;
            box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.6);
        }

        .clock-digit-val {
            font-size: 26px;
            font-weight: 900;
            color: #ffffff;
            font-variant-numeric: tabular-nums;
            line-height: 1;
            font-family: 'Plus Jakarta Sans', monospace;
        }

        .clock-digit-label {
            font-size: 9px;
            font-weight: 800;
            color: #71717a;
            margin-top: 4px;
            letter-spacing: 0.5px;
        }

        .clock-separator {
            font-size: 22px;
            font-weight: 900;
            color: #fbbf24;
            margin-top: -12px;
        }

        /* Mode Switcher Tabs */
        .spin-mode-tabs {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
            background: rgba(19, 20, 28, 0.85);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 20px;
            padding: 6px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
        }

        .spin-mode-tab {
            background: transparent;
            border: none;
            border-radius: 16px;
            padding: 11px 8px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 2px;
            cursor: pointer;
            transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
            color: #94a3b8;
        }

        .spin-mode-tab .tab-icon {
            font-size: 22px;
            margin-bottom: 2px;
            filter: drop-shadow(0 2px 6px rgba(0,0,0,0.5));
        }

        .spin-mode-tab .tab-title {
            font-size: 13px;
            font-weight: 900;
            color: #94a3b8;
            letter-spacing: -0.2px;
        }

        .spin-mode-tab .tab-tag {
            font-size: 10px;
            font-weight: 800;
            opacity: 0.75;
        }

        .spin-mode-tab.active {
            background: linear-gradient(135deg, rgba(168, 85, 247, 0.25) 0%, rgba(124, 58, 237, 0.45) 100%);
            border: 1.5px solid rgba(168, 85, 247, 0.6);
            color: #ffffff;
            box-shadow: 0 4px 20px rgba(168, 85, 247, 0.3);
        }

        .spin-mode-tab.active .tab-title {
            color: #ffffff;
        }

        .spin-mode-tab.active#tabVip {
            background: linear-gradient(135deg, rgba(245, 158, 11, 0.25) 0%, rgba(217, 119, 6, 0.45) 100%);
            border: 1.5px solid rgba(245, 158, 11, 0.7);
            box-shadow: 0 4px 25px rgba(245, 158, 11, 0.35);
        }

        .spin-mode-tab.active#tabVip .tab-title {
            color: #fbbf24;
        }

        .tab-tag.vip-gold {
            color: #fbbf24;
        }

        /* Promocode Voucher Card */
        .promo-voucher-card {
            background: linear-gradient(135deg, rgba(30, 27, 75, 0.65) 0%, rgba(20, 21, 29, 0.95) 100%);
            border: 1px solid rgba(168, 85, 247, 0.35);
            border-radius: 22px;
            padding: 16px 18px;
            margin-bottom: 24px;
            backdrop-filter: blur(12px);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
            box-sizing: border-box;
            width: 100%;
            overflow: hidden;
        }

        .promo-voucher-title {
            display: flex;
            align-items: center;
            justify-content: space-between;
            font-size: 14px;
            font-weight: 800;
            color: #ffffff;
            margin-bottom: 12px;
        }

        .promo-badge-tag {
            font-size: 10px;
            font-weight: 800;
            background: rgba(168, 85, 247, 0.2);
            border: 1px solid rgba(168, 85, 247, 0.4);
            color: #c084fc;
            padding: 3px 8px;
            border-radius: 999px;
        }

        .promo-input-row {
            display: flex;
            gap: 8px;
            align-items: stretch;
            width: 100%;
            box-sizing: border-box;
        }

        .promo-input-row input {
            flex: 1 1 0%;
            min-width: 0;
            background: #11121a;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 16px;
            padding: 12px 14px;
            font-size: 13px;
            font-weight: 700;
            color: #ffffff;
            letter-spacing: 0.8px;
            text-transform: uppercase;
            outline: none;
            transition: all 0.2s ease;
            box-sizing: border-box;
        }

        .promo-input-row input:focus {
            border-color: #c084fc;
            box-shadow: 0 0 15px rgba(192, 132, 252, 0.25);
        }

        .promo-submit-btn {
            flex-shrink: 0;
            background: linear-gradient(135deg, #a855f7 0%, #7e22ce 100%);
            color: #ffffff;
            border: none;
            border-radius: 16px;
            padding: 0 14px;
            font-size: 13px;
            font-weight: 800;
            cursor: pointer;
            transition: all 0.2s ease;
            box-shadow: 0 4px 15px rgba(168, 85, 247, 0.3);
            white-space: nowrap;
            display: flex;
            align-items: center;
            justify-content: center;
            box-sizing: border-box;
        }

        .promo-submit-btn:active {
            transform: scale(0.96);
        }

        .promo-status-msg {
            margin-top: 10px;
            font-size: 12px;
            font-weight: 700;
            padding: 10px 12px;
            border-radius: 12px;
            line-height: 1.4;
        }

        .promo-status-msg.success {
            background: rgba(34, 197, 94, 0.15);
            border: 1px solid rgba(34, 197, 94, 0.4);
            color: #4ade80;
        }

        .promo-status-msg.error {
            background: rgba(239, 68, 68, 0.15);
            border: 1px solid rgba(239, 68, 68, 0.4);
            color: #f87171;
        }

        .promo-channel-hint {
            margin-top: 14px;
            background: linear-gradient(135deg, rgba(2, 132, 199, 0.15) 0%, rgba(14, 165, 233, 0.05) 100%);
            border: 1px dashed rgba(56, 189, 248, 0.45);
            border-radius: 16px;
            padding: 10px 14px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .promo-channel-hint:active {
            background: rgba(2, 132, 199, 0.25);
            transform: scale(0.98);
        }

        .promo-channel-left {
            display: flex;
            align-items: center;
            gap: 10px;
            min-width: 0;
        }

        .promo-channel-icon {
            font-size: 20px;
            flex-shrink: 0;
        }

        .promo-channel-text {
            display: flex;
            flex-direction: column;
            min-width: 0;
        }

        .promo-channel-title {
            font-size: 11px;
            color: #94a3b8;
            font-weight: 700;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .promo-channel-link {
            font-size: 13px;
            color: #38bdf8;
            font-weight: 900;
        }

        .promo-channel-btn {
            background: #0284c7;
            color: #ffffff;
            font-size: 11px;
            font-weight: 800;
            padding: 6px 12px;
            border-radius: 10px;
            white-space: nowrap;
            flex-shrink: 0;
            box-shadow: 0 2px 8px rgba(2, 132, 199, 0.4);
        }

        /* Wheel Stage Container */
        .wheel-stage-container {
            position: relative;
            width: 326px;
            height: 326px;
            margin: 0 auto 24px auto;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .wheel-glowing-aura {
            position: absolute;
            inset: -14px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(251, 191, 36, 0.15) 0%, rgba(56, 189, 248, 0.08) 50%, transparent 70%);
            pointer-events: none;
        }

        /* 3D Metallic Casino Bezel Outer Ring */
        .wheel-outer-ring {
            width: 320px;
            height: 320px;
            border-radius: 50%;
            padding: 10px;
            background: radial-gradient(circle, #1a1b26 0%, #0d0e15 70%, #06070a 100%);
            border: 4px solid #fbbf24;
            box-shadow: 
                0 0 35px rgba(251, 191, 36, 0.45),
                0 15px 35px rgba(0, 0, 0, 0.85),
                inset 0 0 25px rgba(0, 0, 0, 0.95),
                inset 0 2px 4px rgba(255, 255, 255, 0.3);
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            box-sizing: border-box;
        }

        /* Canvas Wheel */
        #wheelCanvas {
            width: 292px;
            height: 292px;
            border-radius: 50%;
            transition: transform 5.2s cubic-bezier(0.15, 0.92, 0.2, 1);
            transform: rotate(0deg) translateZ(0);
            -webkit-transform: rotate(0deg) translateZ(0);
            will-change: transform;
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
        }

        /* Deluxe 3D Center Pin */
        .wheel-center-pin {
            position: absolute;
            width: 58px;
            height: 58px;
            border-radius: 50%;
            background: radial-gradient(circle at 35% 35%, #fde047 0%, #d97706 65%, #78350f 100%);
            border: 3.5px solid #ffffff;
            box-shadow: 
                0 0 25px rgba(0, 0, 0, 0.9),
                0 0 20px rgba(251, 191, 36, 0.9),
                inset 0 2px 5px rgba(255, 255, 255, 0.8),
                inset 0 -3px 6px rgba(0, 0, 0, 0.6);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            z-index: 10;
            pointer-events: none;
            text-shadow: 0 2px 5px rgba(0, 0, 0, 0.5);
        }

        /* High Precision 3D Needle Pointer */
        .wheel-top-pointer {
            position: absolute;
            top: -15px;
            left: 50%;
            transform: translateX(-50%);
            width: 0;
            height: 0;
            border-left: 15px solid transparent;
            border-right: 15px solid transparent;
            border-top: 32px solid #ef4444;
            filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.95)) drop-shadow(0 0 8px rgba(239, 68, 68, 0.6));
            z-index: 25;
            pointer-events: none;
            transition: transform 0.08s ease-out;
            transform-origin: 50% 0%;
        }

        .wheel-top-pointer::after {
            content: '';
            position: absolute;
            top: -32px;
            left: -10px;
            width: 20px;
            height: 10px;
            background: linear-gradient(180deg, #ffffff 0%, #fbbf24 100%);
            border-radius: 6px;
            box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5);
        }

        /* Spin Action Button */
        .spin-action-button {
            width: 100%;
            background: var(--gold-gradient);
            color: #000000;
            border: none;
            border-radius: 20px;
            padding: 18px;
            font-size: 17px;
            font-weight: 900;
            cursor: pointer;
            box-shadow: 0 10px 30px -5px rgba(245, 158, 11, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            letter-spacing: -0.3px;
            transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
            margin-bottom: 16px;
        }

        .spin-action-button:active {
            transform: scale(0.98);
            filter: brightness(1.1);
        }

        .spin-action-button:disabled {
            background: #27272a;
            color: #71717a;
            box-shadow: none;
            cursor: not-allowed;
            transform: none;
        }

        /* Prizes List Grid */
        .prizes-grid-title {
            font-size: 14px;
            font-weight: 800;
            color: #94a3b8;
            margin-bottom: 12px;
            padding: 0 4px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .prizes-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 8px;
            margin-bottom: 24px;
            width: 100%;
            max-width: 100%;
            box-sizing: border-box;
        }

        .prize-item-card {
            background: linear-gradient(135deg, rgba(24, 25, 36, 0.92) 0%, rgba(15, 16, 24, 0.96) 100%);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 16px;
            padding: 10px 8px;
            display: flex;
            align-items: center;
            gap: 8px;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
            box-sizing: border-box;
            min-width: 0;
            width: 100%;
            max-width: 100%;
            overflow: hidden;
            transform: translateZ(0);
            -webkit-transform: translateZ(0);
            transition: transform 140ms cubic-bezier(0.34, 1.56, 0.64, 1), background-color 150ms ease;
            touch-action: manipulation;
        }

        .prize-item-icon {
            width: 36px;
            height: 36px;
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.04);
            border: 1px solid rgba(255, 255, 255, 0.08);
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
            transform: translateZ(0);
            -webkit-transform: translateZ(0);
        }

        .prize-item-icon img {
            width: 26px;
            height: 26px;
            object-fit: contain;
            transform: translateZ(0);
            -webkit-transform: translateZ(0);
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
            will-change: transform;
            image-rendering: auto;
        }

        .prize-item-info {
            display: flex;
            flex-direction: column;
            min-width: 0;
            flex: 1 1 0%;
            overflow: hidden;
        }

        .prize-item-name {
            font-size: 11.5px;
            font-weight: 800;
            color: #ffffff;
            line-height: 1.25;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            width: 100%;
        }

        .prize-item-chance {
            font-size: 9.5px;
            font-weight: 700;
            color: #fbbf24;
            margin-top: 2px;
            line-height: 1.2;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            width: 100%;
        }

        /* Win Modal */
        .win-modal-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.85);
            backdrop-filter: blur(12px);
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            z-index: 1000;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 20px;
        }

        .win-modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .win-modal-card {
            background: linear-gradient(180deg, #181926 0%, #0e0f17 100%);
            border: 1.5px solid rgba(251, 191, 36, 0.6);
            border-radius: 32px;
            padding: 30px 22px 24px;
            width: 100%;
            max-width: 360px;
            text-align: center;
            box-shadow: 0 0 60px rgba(251, 191, 36, 0.35), 0 20px 40px rgba(0, 0, 0, 0.8);
            transform: scale(0.85);
            transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
            display: flex;
            flex-direction: column;
            align-items: center;
            position: relative;
            overflow: hidden;
        }

        .win-modal-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 200px;
            height: 120px;
            background: radial-gradient(ellipse at top, rgba(251, 191, 36, 0.3) 0%, transparent 70%);
            pointer-events: none;
        }

        .win-modal-overlay.active .win-modal-card {
            transform: scale(1);
        }

        .win-badge-tag {
            background: linear-gradient(135deg, rgba(251, 191, 36, 0.2) 0%, rgba(217, 119, 6, 0.3) 100%);
            border: 1px solid rgba(251, 191, 36, 0.5);
            color: #fbbf24;
            font-size: 11px;
            font-weight: 900;
            letter-spacing: 1px;
            text-transform: uppercase;
            padding: 6px 14px;
            border-radius: 999px;
            margin-bottom: 14px;
            display: inline-flex;
            align-items: center;
            gap: 5px;
            box-shadow: 0 0 15px rgba(251, 191, 36, 0.2);
        }

        .win-icon-burst {
            position: relative;
            width: 96px;
            height: 96px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(251, 191, 36, 0.25) 0%, rgba(20, 21, 29, 0.8) 70%);
            border: 2px solid rgba(251, 191, 36, 0.4);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 14px;
            box-shadow: 0 0 30px rgba(251, 191, 36, 0.35);
            animation: bounceWin 2s infinite ease-in-out;
        }

        @keyframes bounceWin {
            0%, 100% { transform: translateY(0) scale(1); }
            50% { transform: translateY(-8px) scale(1.06); }
        }

        .win-title {
            font-size: 24px;
            font-weight: 900;
            background: linear-gradient(135deg, #ffffff 0%, #fbbf24 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            letter-spacing: -0.5px;
            margin-bottom: 4px;
        }

        .win-prize-name {
            font-size: 19px;
            font-weight: 800;
            color: #ffffff;
            margin-bottom: 10px;
        }

        .win-desc {
            font-size: 13px;
            color: #94a3b8;
            font-weight: 600;
            line-height: 1.5;
            margin-bottom: 22px;
            padding: 0 8px;
        }

        .win-actions-col {
            width: 100%;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .win-claim-btn {
            width: 100%;
            background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 50%, #d97706 100%);
            color: #000000;
            border: none;
            border-radius: 18px;
            padding: 16px 18px;
            font-size: 15px;
            font-weight: 900;
            cursor: pointer;
            box-shadow: 0 6px 25px rgba(245, 158, 11, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .win-claim-btn:active {
            transform: scale(0.97);
            filter: brightness(1.1);
        }

        .win-dismiss-btn {
            width: 100%;
            background: rgba(255, 255, 255, 0.08);
            color: #94a3b8;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 16px;
            padding: 13px;
            font-size: 14px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .win-dismiss-btn:active {
            background: rgba(255, 255, 255, 0.15);
            transform: scale(0.98);
        }
